CREATE TABLE #CountryCodes (
    code CHAR(3) NOT NULL
);

INSERT INTO #CountryCodes (code) VALUES ('US'), ('USA'), ('GB');

SELECT
    code,
    LEN(code)        AS char_length,
    DATALENGTH(code) AS stored_bytes,
    CASE WHEN code = 'US' THEN 'match' ELSE 'no match' END AS equality
FROM #CountryCodes
ORDER BY code;
